package com.clavis.reader;
import android.content.Context;import android.util.AtomicFile;import org.json.*;import org.jsoup.*;import org.jsoup.nodes.*;import org.jsoup.parser.Parser;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
/** Bounded metadata pages from the publishers, persisted separately from the snapshot. */
final class CatalogRepository {
 static final int LIMIT=1000,BATCH=25;
 static final ExecutorService worker=Executors.newSingleThreadExecutor();
 static final class State {final ArrayList<JSONObject> items=new ArrayList<>();int offset;boolean exhausted;}
 static File file(Context c,boolean audio){return new File(c.getFilesDir(),audio?"catalog-audio-pages.json":"catalog-ebook-pages.json");}
 static State load(Context c,boolean audio)throws Exception{State state=new State();HashSet<String> ids=new HashSet<>();for(JSONObject item:StarterCatalog.load(c))if(audio==item.optString("kind").equals("Audio")){state.items.add(item);ids.add(item.getString("id"));}state.offset=state.items.size();try{JSONObject saved=new JSONObject(new String(new AtomicFile(file(c,audio)).readFully(),StandardCharsets.UTF_8));JSONArray entries=saved.getJSONArray("items");for(int i=0;i<entries.length()&&state.items.size()<LIMIT;i++){JSONObject item=entries.getJSONObject(i);if(audio==item.optString("kind").equals("Audio")&&ids.add(item.getString("id")))state.items.add(item);}state.offset=Math.max(state.offset,saved.getInt("offset"));state.exhausted=saved.optBoolean("exhausted");}catch(Exception ignored){}return state;}
 static void save(Context c,boolean audio,State state)throws Exception{JSONObject json=new JSONObject().put("offset",state.offset).put("exhausted",state.exhausted).put("items",new JSONArray(state.items));AtomicFile target=new AtomicFile(file(c,audio));FileOutputStream out=target.startWrite();try{out.write(json.toString().getBytes(StandardCharsets.UTF_8));target.finishWrite(out);}catch(Exception e){target.failWrite(out);throw e;}}
 static String get(String url)throws Exception{HttpURLConnection connection=FeedStore.connect(url,10000,20000);try(InputStream in=connection.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1){if(out.size()+n>4*1024*1024)throw new IOException("Catalog response too large");out.write(buffer,0,n);}return out.toString("UTF-8");}finally{connection.disconnect();}}
 static ArrayList<JSONObject> ebooks(String xml,int offset)throws Exception{ArrayList<JSONObject> result=new ArrayList<>();Document document=Jsoup.parse(xml,"https://www.gutenberg.org",Parser.xmlParser());for(Element entry:document.select("feed > entry")){String source=entry.select("id").text();java.util.regex.Matcher id=java.util.regex.Pattern.compile("/ebooks/([0-9]+)").matcher(source);if(!id.find())continue;String number=id.group(1);result.add(new JSONObject().put("id","pg-"+number).put("kind","EPUB").put("rank",offset+result.size()+1).put("title",entry.select("title").text()).put("author",entry.select("content").text()).put("source","https://www.gutenberg.org/ebooks/"+number).put("download","https://www.gutenberg.org/ebooks/"+number+".epub3.images").put("rights","Refer to the source edition's license; availability does not establish worldwide public-domain status.").put("rightsUrl","https://www.gutenberg.org/policy/license").put("evidence","https://www.gutenberg.org/cache/epub/"+number+"/pg"+number+".rdf"));}return result;}
 static JSONObject audio(JSONObject document,int rank)throws Exception{JSONObject meta=document.getJSONObject("metadata");String id=meta.getString("identifier"),zip="";long size=0;JSONArray files=document.getJSONArray("files");for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);String name=f.optString("name");if(name.endsWith("_64kb_mp3.zip")){zip=name;size=f.optLong("size");break;}if(name.endsWith("_vbr_mp3.zip")){zip=name;size=f.optLong("size");}}if(zip.isEmpty()){boolean low=false,vbr=false;long lowBytes=0,vbrBytes=0;for(int i=0;i<files.length();i++){JSONObject f=files.getJSONObject(i);if(f.optString("format").equals("64Kbps MP3")){low=true;lowBytes+=f.optLong("size");}if(f.optString("format").equals("VBR MP3")){vbr=true;vbrBytes+=f.optLong("size");}}if(!low&&!vbr)return null;zip=id+(low?"_64kb_mp3.zip":"_vbr_mp3.zip");size=low?lowBytes:vbrBytes;}
 Object author=meta.opt("creator");String creator=author instanceof JSONArray?((JSONArray)author).join("; ").replace("\"",""):meta.optString("creator");return new JSONObject().put("id","lv-"+id).put("kind","Audio").put("rank",rank).put("title",meta.optString("title")).put("author",creator).put("source","https://archive.org/details/"+id).put("download","https://archive.org/download/"+id+"/"+URLEncoder.encode(zip,"UTF-8").replace("+","%20")).put("bytes",size).put("rights","LibriVox source; check the original text and recording license for your jurisdiction.").put("rightsUrl","https://librivox.org/pages/public-domain/").put("recordingLicense",meta.optString("licenseurl")).put("evidence","https://archive.org/metadata/"+id);}
 static ArrayList<JSONObject> recordings(int offset,String search)throws Exception{String query="collection:librivoxaudio AND language:eng AND mediatype:audio";if(!search.isEmpty()){String term=search.replace("\\","\\\\").replace("\"","\\\"");query+=" AND (title:\""+term+"\" OR creator:\""+term+"\")";}JSONObject response=new JSONObject(get("https://archive.org/advancedsearch.php?q="+URLEncoder.encode(query,"UTF-8")+"&fl[]=identifier&fl[]=title&fl[]=creator&sort[]=downloads%20desc&rows=25&page="+(offset/BATCH+1)+"&output=json")).getJSONObject("response");JSONArray docs=response.getJSONArray("docs");ArrayList<JSONObject> result=new ArrayList<>();for(int i=0;i<docs.length();i++){JSONObject doc=docs.getJSONObject(i);String id=doc.getString("identifier");Object author=doc.opt("creator");String creator=author instanceof JSONArray?((JSONArray)author).join("; ").replace("\"",""):doc.optString("creator");result.add(new JSONObject().put("id","lv-"+id).put("kind","Audio").put("rank",offset+i+1).put("title",doc.optString("title")).put("author",creator).put("source","https://archive.org/details/"+id).put("rightsUrl","https://librivox.org/pages/public-domain/").put("rights","Refer to the original text and recording license.").put("evidence","https://archive.org/metadata/"+id).put("pendingAudio",true));}return result;}
 static State search(boolean audio,String query,State state)throws Exception{ArrayList<JSONObject> batch=audio?recordings(state.offset,query):ebooks(get("https://www.gutenberg.org/ebooks/search/?sort_order=downloads&format=opds&query="+URLEncoder.encode(query,"UTF-8")+"&start_index="+(state.offset+1)),state.offset);state.offset+=BATCH;state.exhausted=batch.size()<BATCH;append(state,batch);return state;}
 static void append(State state,List<JSONObject> batch)throws Exception{HashSet<String> ids=new HashSet<>();for(JSONObject item:state.items)ids.add(item.getString("id"));for(JSONObject item:batch)if(item!=null&&state.items.size()<LIMIT&&ids.add(item.getString("id")))state.items.add(item);}
 static State next(Context c,boolean audio)throws Exception{State state=load(c,audio);if(state.exhausted||state.items.size()>=LIMIT)return state;ArrayList<JSONObject> batch=audio?recordings(state.offset,""):ebooks(get("https://www.gutenberg.org/ebooks/search/?sort_order=downloads&format=opds&start_index="+(state.offset+1)),state.offset);state.offset+=BATCH;state.exhausted=batch.size()<BATCH;append(state,batch);save(c,audio,state);return state;}
 static String artwork(JSONObject item){String id=item.optString("id");if(id.startsWith("pg-"))return "https://www.gutenberg.org/cache/epub/"+id.substring(3)+"/pg"+id.substring(3)+".cover.medium.jpg";if(id.startsWith("lv-"))return "https://archive.org/services/img/"+id.substring(3);return "";}
}
